type JsonObject = Record<string, any>;

export interface ClientGeneratorOptions {
  /** Module specifier, relative to the generated file, that exports the models. */
  readonly models: string;
}

/** Generate a small fetch client from framework OpenAPI metadata. */
export function generateClient(
  document: JsonObject,
  options: ClientGeneratorOptions,
): string {
  if (!document || typeof document !== "object" || !document.paths) {
    throw new TypeError("The input is not an OpenAPI document with paths");
  }
  if (!options.models.trim()) {
    throw new TypeError("A model module specifier is required");
  }

  const schemas: Record<string, JsonObject> =
    document.components?.schemas ?? {};
  const modelAliases = createModelAliases(schemas);
  const root: ClientNode = { methods: [], children: new Map() };
  const imports = new Set<string>();

  for (const [path, pathItem] of Object.entries<JsonObject>(document.paths)) {
    for (const [method, operation] of Object.entries<JsonObject>(pathItem)) {
      if (!httpMethods.has(method.toLowerCase()) || !operation) continue;
      const node = getClientNode(root, getResourcePath(path));
      const name = createResourceMethodName(operation, method, path);
      if (node.methods.some((entry) => entry.name === name)) {
        throw new TypeError(
          `Duplicate generated client method name for ${path}: ${name}`,
        );
      }
      node.methods.push({
        name,
        source: generateOperation(
          path,
          method.toUpperCase(),
          operation,
          schemas,
          modelAliases,
          imports,
          name,
        ),
      });
    }
  }

  const importLine = [...imports].sort().join(", ");
  return `/* Generated by @restfx/client. Do not edit. */
import { validateModel } from "@restfx/core";
import { ApiError, createApiClientRuntime } from "@restfx/client";
import type { ClientOptions } from "@restfx/client";
${importLine ? `import { ${importLine} } from ${JSON.stringify(options.models)};\n` : ""}
export { ApiError };

export function createApiClient(options: ClientOptions = {}) {
  const runtime = createApiClientRuntime(options);
  return ${renderClientNode(root, 2)};
}
`;
}

const httpMethods = new Set([
  "get",
  "put",
  "post",
  "delete",
  "options",
  "head",
  "patch",
  "trace",
]);

interface ClientNode {
  readonly methods: Array<{ readonly name: string; readonly source: string }>;
  readonly children: Map<string, ClientNode>;
}

function getResourcePath(path: string) {
  return path
    .split("/")
    .filter((segment) => segment && !/^\{[^{}]+\}$/.test(segment))
    .map((segment) => safeIdentifier(segment));
}

function getClientNode(root: ClientNode, resourcePath: string[]) {
  let node = root;
  for (const segment of resourcePath) {
    let child = node.children.get(segment);
    if (!child) {
      child = { methods: [], children: new Map() };
      node.children.set(segment, child);
    }
    node = child;
  }
  return node;
}

function createResourceMethodName(
  operation: JsonObject,
  method: string,
  path: string,
) {
  const resourcePath = getResourcePath(path);
  if (resourcePath.length === 0) {
    return createMethodName(operation.operationId, method, path);
  }

  const operationId = operation.operationId;
  const operationAction =
    typeof operationId === "string"
      ? /^(list|create|add|post|read|get|fetch|update|patch|replace|put|delete|remove|archive|restore|head|options|trace)(?=[A-Z]|$)/i
          .exec(operationId)?.[1]
          ?.toLowerCase()
      : undefined;
  if (operationAction) {
    switch (operationAction) {
      case "add":
      case "post":
        return "create";
      case "read":
      case "fetch":
        return "get";
      case "patch":
      case "replace":
      case "put":
        return "update";
      case "remove":
        return "delete";
      default:
        return operationAction;
    }
  }

  const isItemPath = /\{[^{}]+\}\/?$/.test(path);
  switch (method.toUpperCase()) {
    case "GET":
    case "HEAD":
      return isItemPath ? "get" : "list";
    case "POST":
      return "create";
    case "PUT":
    case "PATCH":
      return "update";
    case "DELETE":
      return "delete";
    default:
      return method.toLowerCase();
  }
}

function renderClientNode(node: ClientNode, indentLevel: number): string {
  const entries = node.methods.map(({ source }) => source);
  for (const [name, child] of node.children) {
    entries.push(`${name}: ${renderClientNode(child, indentLevel + 2)}`);
  }
  const closingIndent = " ".repeat(indentLevel);
  return `{
${entries.map((entry) => indent(entry, indentLevel + 2)).join(",\n")}
${closingIndent}}`;
}

function generateOperation(
  path: string,
  method: string,
  operation: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
  methodName: string,
) {
  const metadata = getOperationMetadata(
    path,
    method,
    operation,
    schemas,
    modelAliases,
    imports,
  );
  const {
    fields,
    parameters,
    requestModel,
    bodyModel,
    bodyProperty,
    requestBody,
    requestContentType,
    hasInput,
    inputType,
    responseType,
    responseContentTypes,
    emptySuccessStatuses,
  } = metadata;
  const lines = [
    `${methodName}: async (${hasInput ? `input: ${inputType}` : ""}): Promise<${responseType}> => {`,
  ];
  appendModelInputLines(
    lines,
    fields,
    requestModel,
    bodyModel,
    bodyProperty,
    requestContentType,
  );
  appendBodyLines(
    lines,
    requestModel,
    bodyModel,
    bodyProperty,
    requestContentType,
  );

  const pathExpression = createPathExpression(
    path,
    parameters,
    fields,
    Boolean(requestModel),
  );
  lines.push(`  const url = runtime.createUrl(${pathExpression});`);
  appendParameterLines(lines, parameters, fields, Boolean(requestModel));
  appendHeaderLines(lines, parameters, requestContentType);

  const requestBodyValue = bodyModel ? "body" : "input.body";
  const bodyExpression = requestBody
    ? serializeRequestBody(requestBodyValue, requestContentType)
    : undefined;
  lines.push(
    `  return await runtime.sendRequest<${responseType}>(url, { method: ${JSON.stringify(method)}, headers${bodyExpression ? `, body: ${bodyExpression}` : ""} }, ${JSON.stringify(responseContentTypes[0] ?? "")}, ${JSON.stringify(responseType === "void" ? [] : emptySuccessStatuses)}, ${responseType !== "void"});`,
  );
  lines.push("}");
  return lines.join("\n");
}

function getOperationMetadata(
  path: string,
  method: string,
  operation: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const clientMetadata = operation["x-restfx-client"] ?? {};
  const requestModelRef = clientMetadata.requestModel?.$ref as
    string | undefined;
  const requestModel = requestModelRef
    ? modelAliases.get(requestModelRef)
    : undefined;
  if (requestModelRef && !requestModel) {
    throw new TypeError(`No shared model is mapped for ${requestModelRef}`);
  }
  if (requestModel) imports.add(requestModel);

  const fields: Array<{ property: string; source: string; name: string }> =
    clientMetadata.fields ?? [];
  const parameters = mergeParameters(operation.parameters ?? []);
  const cookieParameter = parameters.find(
    (parameter) => parameter.in === "cookie",
  );
  if (cookieParameter) {
    throw new TypeError(
      `${method} ${path} uses a cookie parameter; cookie-based API parameters are not supported by the generated fetch client`,
    );
  }
  if (requestModel) {
    validateRequestModelParameters(path, method, parameters, fields);
  }

  const bodyMetadata = clientMetadata.body;
  const bodyRef = bodyMetadata?.model?.$ref as string | undefined;
  const bodyModel = bodyRef ? modelAliases.get(bodyRef) : undefined;
  if (bodyRef && !bodyModel) {
    throw new TypeError(`No shared model is mapped for ${bodyRef}`);
  }
  if (bodyModel) imports.add(bodyModel);

  const requestBody = operation.requestBody;
  const requestContent = requestBody?.content;
  const requestContentType = requestContent
    ? Object.keys(requestContent)[0]
    : undefined;
  const requestSchema = requestContentType
    ? requestContent[requestContentType]?.schema
    : undefined;
  const bodyProperty = bodyMetadata?.property ?? "body";

  const hasInput = Boolean(requestModel || parameters.length || requestBody);
  const inputType = createOperationInputType(
    requestModel,
    hasInput,
    requestBody,
    parameters,
    requestContentType,
    bodyModel,
    requestSchema,
    schemas,
    modelAliases,
    imports,
  );

  const responseType = getResponseType(
    operation.responses ?? {},
    schemas,
    modelAliases,
    imports,
  );
  const responseContentTypes = getSuccessfulResponseContentTypes(
    operation.responses ?? {},
  );
  const emptySuccessStatuses = Object.entries<JsonObject>(
    operation.responses ?? {},
  )
    .filter(
      ([status, response]) =>
        /^(?:2\d\d|2XX)$/.test(status) && !response.content,
    )
    .map(([status]) => status)
    .filter((status) => /^2\d\d$/.test(status))
    .map((status) => Number(status));
  return {
    fields,
    parameters,
    requestModel,
    bodyModel,
    bodyProperty,
    requestBody,
    requestContentType,
    hasInput,
    inputType,
    responseType,
    responseContentTypes,
    emptySuccessStatuses,
  };
}

function validateRequestModelParameters(
  path: string,
  method: string,
  parameters: JsonObject[],
  fields: Array<{ property: string; source: string; name: string }>,
) {
  const unmatched = parameters.find(
    (parameter) =>
      !fields.some(
        (field) =>
          field.source === parameter.in && field.name === parameter.name,
      ),
  );
  if (unmatched) {
    throw new TypeError(
      `${method} ${path} has an OpenAPI parameter ${unmatched.in}:${unmatched.name} not represented by its request model`,
    );
  }
}

function createOperationInputType(
  requestModel: string | undefined,
  hasInput: boolean,
  requestBody: JsonObject | undefined,
  parameters: JsonObject[],
  requestContentType: string | undefined,
  bodyModel: string | undefined,
  requestSchema: JsonObject | undefined,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  if (requestModel) {
    if (!requestBody || bodyModel) return requestModel;
    return `${requestModel} & ${createInputType(
      [],
      requestBody,
      requestContentType,
      undefined,
      requestSchema,
      schemas,
      modelAliases,
      imports,
    )}`;
  }
  if (!hasInput) return "";
  return createInputType(
    parameters,
    requestBody,
    requestContentType,
    bodyModel,
    requestSchema,
    schemas,
    modelAliases,
    imports,
  );
}

function appendModelInputLines(
  lines: string[],
  fields: Array<{ property: string; source: string; name: string }>,
  requestModel: string | undefined,
  bodyModel: string | undefined,
  bodyProperty: string,
  requestContentType: string | undefined,
) {
  if (!requestModel) return;
  lines.push(
    `  const requestInput = runtime.copyDefinedProperties(input, ${JSON.stringify(fields.map(({ property }) => property))});`,
  );
  if (bodyModel) {
    appendBodyInputLines(
      lines,
      `Reflect.get(input, ${JSON.stringify(bodyProperty)})`,
      requestContentType,
    );
    lines.push(
      `  if (Object.hasOwn(input, ${JSON.stringify(bodyProperty)})) requestInput[${JSON.stringify(bodyProperty)}] = bodyInput;`,
    );
  }
  lines.push(`  const request = validateModel(requestInput, ${requestModel});`);
}

function appendBodyLines(
  lines: string[],
  requestModel: string | undefined,
  bodyModel: string | undefined,
  bodyProperty: string,
  requestContentType: string | undefined,
) {
  if (!bodyModel) return;
  if (requestModel) {
    lines.push(`  const body = request[${JSON.stringify(bodyProperty)}];`);
    return;
  }
  appendBodyInputLines(lines, "input.body", requestContentType);
  lines.push(`  const body = validateModel(bodyInput, ${bodyModel});`);
}

function appendParameterLines(
  lines: string[],
  parameters: JsonObject[],
  fields: Array<{ property: string; source: string; name: string }>,
  hasRequestModel: boolean,
) {
  for (const [index, parameter] of parameters.entries()) {
    const access = getParameterAccess(parameter, fields, hasRequestModel);
    if (parameter.in === "query") {
      lines.push(
        `  runtime.appendQuery(url, ${JSON.stringify(parameter.name)}, ${access});`,
      );
    } else if (parameter.in === "header") {
      lines.push(`  const header_${index} = ${access};`);
    }
  }
}

function appendHeaderLines(
  lines: string[],
  parameters: JsonObject[],
  requestContentType: string | undefined,
) {
  lines.push("  const headers = new Headers();");
  for (const [index, parameter] of parameters.entries()) {
    if (parameter.in !== "header") continue;
    const local = `header_${index}`;
    lines.push(
      `  if (${local} !== undefined) headers.set(${JSON.stringify(parameter.name)}, Array.isArray(${local}) ? ${local}.join(",") : String(${local}));`,
    );
  }
  if (!requestContentType) return;
  if (isMultipartContentType(requestContentType)) {
    lines.push('  headers.delete("content-type");');
  } else {
    lines.push(
      `  headers.set("content-type", ${JSON.stringify(requestContentType)});`,
    );
  }
}

function appendBodyInputLines(
  lines: string[],
  inputExpression: string,
  contentType: string | undefined,
) {
  if (!isJsonContentType(contentType)) {
    lines.push(`  const bodyInput = ${inputExpression};`);
    return;
  }

  lines.push(
    `  const serializedBodyInput = JSON.stringify(${inputExpression});`,
  );
  lines.push(
    "  const bodyInput = serializedBodyInput === undefined ? undefined : JSON.parse(serializedBodyInput);",
  );
}

function createInputType(
  parameters: JsonObject[],
  requestBody: JsonObject | undefined,
  requestContentType: string | undefined,
  bodyModel: string | undefined,
  bodySchema: JsonObject | undefined,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const groups = ["path", "query", "header"] as const;
  const properties: string[] = [];
  for (const group of groups) {
    const groupParameters = parameters.filter(
      (parameter) => parameter.in === group,
    );
    if (!groupParameters.length) continue;
    const required = groupParameters.some((parameter) => parameter.required);
    const fields = groupParameters.map(
      (parameter) =>
        `${JSON.stringify(parameter.name)}${parameter.required ? "" : "?"}: ${schemaToType(parameter.schema ?? {}, schemas, modelAliases, imports)}`,
    );
    properties.push(`${group}${required ? "" : "?"}: { ${fields.join("; ")} }`);
  }
  if (requestBody) {
    let type =
      bodyModel ??
      schemaToType(bodySchema ?? {}, schemas, modelAliases, imports);
    if (isMultipartContentType(requestContentType)) {
      type = `(${type}) | FormData`;
    } else if (isUrlEncodedContentType(requestContentType)) {
      type = `(${type}) | URLSearchParams`;
    } else if (isBinaryContentType(requestContentType)) {
      type = "Blob | ArrayBuffer | ArrayBufferView";
    }
    properties.push(
      `body${requestBody.required === false ? "?" : ""}: ${type}`,
    );
  }
  return `{ ${properties.join("; ")} }`;
}

function getResponseType(
  responses: Record<string, JsonObject>,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const successful = Object.entries(responses).filter(([status]) =>
    /^(?:2\d\d|2XX)$/.test(status),
  );
  if (!successful.length) return "void";
  const types = successful.flatMap(([, response]) => {
    const content = response.content;
    if (!content) return ["void"];
    return Object.entries<JsonObject>(content).map(([contentType, media]) =>
      responseMediaTypeToType(
        contentType,
        media?.schema ?? {},
        schemas,
        modelAliases,
        imports,
      ),
    );
  });
  return [...new Set(types)].join(" | ");
}

function getSuccessfulResponseContentTypes(
  responses: Record<string, JsonObject>,
) {
  return Object.entries<JsonObject>(responses)
    .filter(([status]) => /^(?:2\d\d|2XX)$/.test(status))
    .flatMap(([, response]) => Object.keys(response.content ?? {}));
}

function responseMediaTypeToType(
  contentType: string,
  schema: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  if (isJsonContentType(contentType)) {
    return schemaToType(schema, schemas, modelAliases, imports);
  }
  if (isTextContentType(contentType)) return "string";
  if (isUrlEncodedContentType(contentType)) return "URLSearchParams";
  if (isMultipartContentType(contentType)) return "FormData";
  return "Blob";
}

function serializeRequestBody(value: string, contentType: string | undefined) {
  if (!contentType || isJsonContentType(contentType)) {
    return `JSON.stringify(${value})`;
  }
  if (isMultipartContentType(contentType)) {
    return `runtime.toFormData(${value})`;
  }
  if (isUrlEncodedContentType(contentType)) {
    return `runtime.toUrlSearchParams(${value})`;
  }
  return `(${value} as BodyInit)`;
}

function schemaToType(
  schema: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
): string {
  if (schema.format === "binary") return "Blob";
  if (schema.$ref)
    return referenceToType(schema.$ref, schemas, modelAliases, imports);
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  if (Array.isArray(schema.enum)) return enumToType(schema.enum);
  const alternatives = schema.anyOf ?? schema.oneOf ?? schema.allOf;
  if (Array.isArray(alternatives))
    return alternativesToType(
      alternatives,
      schema.allOf,
      schemas,
      modelAliases,
      imports,
    );
  if (schema.type === "array")
    return arraySchemaToType(schema, schemas, modelAliases, imports);
  if (schema.type === "object" || schema.properties)
    return objectSchemaToType(schema, schemas, modelAliases, imports);
  if (Array.isArray(schema.type)) {
    return schema.type.map((type: string) => primitiveType(type)).join(" | ");
  }
  return primitiveType(schema.type);
}

function referenceToType(
  reference: string,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const alias = modelAliases.get(reference);
  if (alias) {
    imports.add(alias);
    return alias;
  }
  const target = schemas[reference.split("/").at(-1)!];
  return target
    ? schemaToType(target, schemas, modelAliases, imports)
    : "unknown";
}

function enumToType(values: unknown[]) {
  return values.map((value) => JSON.stringify(value)).join(" | ") || "never";
}

function alternativesToType(
  alternatives: JsonObject[],
  intersection: unknown,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const separator = intersection ? " & " : " | ";
  return alternatives
    .map((part) => schemaToType(part, schemas, modelAliases, imports))
    .join(separator);
}

function arraySchemaToType(
  schema: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const itemType = schemaToType(
    schema.items ?? {},
    schemas,
    modelAliases,
    imports,
  );
  return `(${itemType})[]`;
}

function objectSchemaToType(
  schema: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const required = new Set<string>(schema.required ?? []);
  const properties = Object.entries<JsonObject>(schema.properties ?? {}).map(
    ([name, property]) =>
      `${JSON.stringify(name)}${required.has(name) ? "" : "?"}: ${schemaToType(property, schemas, modelAliases, imports)}`,
  );
  if (
    schema.additionalProperties &&
    typeof schema.additionalProperties === "object"
  ) {
    properties.push(
      `[key: string]: ${schemaToType(schema.additionalProperties, schemas, modelAliases, imports)}`,
    );
  }
  return properties.length
    ? `{ ${properties.join("; ")} }`
    : "Record<string, unknown>";
}

function primitiveType(type: string | undefined) {
  switch (type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "object":
      return "Record<string, unknown>";
    case "array":
      return "unknown[]";
    default:
      return "unknown";
  }
}

function createPathExpression(
  path: string,
  parameters: JsonObject[],
  fields: Array<{ property: string; source: string; name: string }>,
  hasRequestModel: boolean,
) {
  const parts = path.split(/(\{[^{}]+\})/g);
  const expression = parts.map((part) => {
    const match = /^\{([^{}]+)\}$/.exec(part);
    if (!match) return escapeTemplateLiteral(part);
    const name = match[1]!;
    const parameter = parameters.find(
      (item) => item.in === "path" && item.name === name,
    );
    const access = parameter
      ? getParameterAccess(parameter, fields, hasRequestModel)
      : "undefined";
    if (access === "undefined")
      throw new TypeError(`Path parameter ${name} is not declared`);
    return `\${encodeURIComponent(String(${access}))}`;
  });
  return "`" + expression.join("") + "`";
}

function getParameterAccess(
  parameter: JsonObject,
  fields: Array<{ property: string; source: string; name: string }>,
  hasRequestModel: boolean,
) {
  if (hasRequestModel) {
    const field = fields.find(
      (item) => item.source === parameter.in && item.name === parameter.name,
    );
    return field ? `request[${JSON.stringify(field.property)}]` : "undefined";
  }
  const group = parameter.in === "header" ? "header" : parameter.in;
  return `input.${group}?.[${JSON.stringify(parameter.name)}]`;
}

function mergeParameters(parameters: JsonObject[]) {
  const merged = new Map<string, JsonObject>();
  for (const parameter of parameters) {
    if (!parameter || typeof parameter.name !== "string") continue;
    merged.set(`${parameter.in}:${parameter.name}`, parameter);
  }
  return [...merged.values()];
}

function createModelAliases(schemas: Record<string, JsonObject>) {
  const result = new Map<string, string>();
  const names = new Map<string, number>();
  for (const [schemaName, schema] of Object.entries(schemas)) {
    const className = schema["x-restfx-model"];
    if (typeof className !== "string" || !className) continue;
    const count = names.get(className) ?? 0;
    if (count > 0) {
      throw new TypeError(
        `Multiple OpenAPI models use the exported TypeScript name ${className}; expose uniquely named model classes to generate a client`,
      );
    }
    names.set(className, count + 1);
    const alias = className;
    result.set(`#/components/schemas/${schemaName}`, alias);
  }
  return result;
}

function createMethodName(operationId: unknown, method: string, path: string) {
  const raw =
    typeof operationId === "string" && operationId
      ? operationId
      : `${method.toLowerCase()}_${path.replace(/[{}:]/g, "").replace(/[^A-Za-z0-9]+/g, "_")}`;
  const identifier = safeIdentifier(raw);
  return /^[A-Za-z_$]/.test(identifier)
    ? identifier
    : `operation_${identifier}`;
}

function safeIdentifier(value: string) {
  return value.replace(/[^A-Za-z0-9_$]/g, "_");
}

function escapeTemplateLiteral(value: string) {
  return value
    .replaceAll("\\", "\\\\")
    .replaceAll("`", "\\`")
    .replaceAll("${", "\\${");
}

function isJsonContentType(contentType: string | undefined) {
  return Boolean(
    contentType &&
    (contentType.toLowerCase().split(";")[0] === "application/json" ||
      contentType.toLowerCase().split(";")[0]?.endsWith("+json")),
  );
}

function isMultipartContentType(contentType: string | undefined) {
  return contentType?.toLowerCase().startsWith("multipart/form-data") ?? false;
}

function isUrlEncodedContentType(contentType: string | undefined) {
  return (
    contentType
      ?.toLowerCase()
      .startsWith("application/x-www-form-urlencoded") ?? false
  );
}

function isBinaryContentType(contentType: string | undefined) {
  return Boolean(
    contentType &&
    !isJsonContentType(contentType) &&
    !isMultipartContentType(contentType) &&
    !isUrlEncodedContentType(contentType) &&
    !isTextContentType(contentType),
  );
}

function isTextContentType(contentType: string) {
  const normalized = contentType.toLowerCase().split(";")[0] ?? "";
  return (
    normalized.startsWith("text/") ||
    normalized === "application/xml" ||
    normalized.endsWith("+xml") ||
    normalized === "application/javascript" ||
    normalized === "application/ecmascript"
  );
}

function indent(value: string, spaces: number) {
  const prefix = " ".repeat(spaces);
  return value
    .split("\n")
    .map((line) => `${prefix}${line}`)
    .join("\n");
}
